public static int bestRow(int[][] grid) {
    int bestIndex = 0;
    int bestSum = 0;
    for (int c = 0; c < grid[0].length; c++) bestSum += grid[0][c];
    for (int r = 1; r < grid.length; r++) {
        int sum = 0;
        for (int c = 0; c < grid[r].length; c++) sum += grid[r][c];
        if (sum > bestSum) { bestSum = sum; bestIndex = r; }
    }
    return bestIndex;
}

public static ArrayList<Integer> aboveAverage(ArrayList<Integer> data) {
    ArrayList<Integer> result = new ArrayList<Integer>();
    if (data.size() == 0) return result;
    int sum = 0;
    for (int v : data) sum += v;
    double avg = (double) sum / data.size();
    for (int v : data) {
        if (v > avg) result.add(v);
    }
    return result;
}

public class StepTracker {
    private int minActive;
    private int totalSteps;
    private int numDays;
    private int activeCount;

    public StepTracker(int minActive) {
        this.minActive = minActive;
        totalSteps = 0;
        numDays = 0;
        activeCount = 0;
    }

    public void addDailySteps(int steps) {
        totalSteps += steps;
        numDays++;
        if (steps >= minActive) {
            activeCount++;
        }
    }

    public int activeDays() {
        return activeCount;
    }

    public double averageSteps() {
        if (numDays == 0) {
            return 0.0;
        }
        return (double) totalSteps / numDays;
    }
}

public static int countUpper(String s) {
  int count = 0;
  for (int i = 0; i < s.length(); i++) {
    String c = s.substring(i, i + 1);
    if (c.compareTo("A") >= 0 && c.compareTo("Z") <= 0) count++;
  }
  return count;
}

public static String rate(String s) {
  int up = countUpper(s);
  int len = s.length();
  if (len >= 8 && up >= 2) return "strong";
  if (len >= 8 || up >= 1) return "medium";
  return "weak";
}

